# Check for vertical periodicity in the unique 9-column pattern
rows = len(period_0)
periods_v = []
for v_period in range(1, rows // 2):
    match = True
    for r in range(v_period):
        for c in range(9):
            if period_0[r][c] != period_0[r + v_period][c]:
                match = False
                break
        if not match:
            break
    periods_v.append((v_period, match))

print(f"Vertical period candidates: {periods_v[:15]}")

# Look at each column's pattern
print("\nColumn values in the 9-column period:")
for c in range(9):
    col = [row[c] for row in period_0]
    print(f"Col {c}: {col}")

# Count frequency of each value
from collections import Counter
value_counts = Counter()
for row in period_0:
    for val in row:
        value_counts[val] += 1
print(f"\nValue frequencies: {dict(sorted(value_counts.items()))}")
